import java.text.Normalizer;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import java.util.regex.Pattern;

/**
 * A filter understood by {@link CustomerRepository}.
 *
 * @param name     free text; split on whitespace into terms, every term of
 *                 which must appear as a substring of the customer's first or
 *                 last name. Blank matches every customer.
 * @param statuses statuses a customer must have one of; empty matches every
 *                 customer
 */
public record CustomerFilter(String name, Set<CustomerStatus> statuses) {

    public static final CustomerFilter EMPTY = new CustomerFilter("", Set.of());

    private static final Pattern WHITESPACE = Pattern.compile("\\s+");
    private static final Pattern COMBINING_MARKS = Pattern.compile("\\p{M}");

    public CustomerFilter {
        name = name == null ? "" : name;
        statuses = statuses == null ? Set.of() : Set.copyOf(statuses);
    }

    /** The name filter split into normalized, non-blank search terms. */
    public List<String> nameTerms() {
        return WHITESPACE.splitAsStream(name.strip())
                .filter(term -> !term.isBlank())
                .map(CustomerFilter::normalize)
                .toList();
    }

    /** Whether the given customer satisfies both the name and status filters. */
    public boolean matches(Customer customer) {
        return matchesName(customer) && matchesStatus(customer);
    }

    private boolean matchesName(Customer customer) {
        List<String> terms = nameTerms();
        if (terms.isEmpty()) {
            return true;
        }
        String first = normalize(customer.firstName());
        String last = normalize(customer.lastName());
        return terms.stream().allMatch(term -> first.contains(term) || last.contains(term));
    }

    private boolean matchesStatus(Customer customer) {
        return statuses.isEmpty() || statuses.contains(customer.status());
    }

    /** Lower-cases and strips diacritics, so matching ignores case and accents. */
    private static String normalize(String s) {
        String decomposed = Normalizer.normalize(s, Normalizer.Form.NFD);
        return COMBINING_MARKS.matcher(decomposed).replaceAll("").toLowerCase(Locale.ROOT);
    }
}
