[metadata] {"type": "create", "filePath": "/app/src/main/java/com/example/customers/ui/FilterUrlCodec.java", "content": "package com.example.customers.ui;

import java.net.URLEncoder;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;
import java.util.stream.Collectors;

import com.example.customers.domain.CustomerFilter;
import com.example.customers.domain.CustomerStatus;

import com.vaadin.flow.router.QueryParameters;

/**
 * Converts a {@link CustomerFilter} to and from the {@code name} and
 * {@code status} query parameters carried in {@link CustomerListView}'s URL.
 */
final class FilterUrlCodec {

    static final String PARAM_NAME = "name";
    static final String PARAM_STATUS = "status";

    private FilterUrlCodec() {
    }

    /** Reads a filter out of a URL's query parameters; missing parameters mean no filtering. */
    static CustomerFilter parse(QueryParameters queryParameters) {
        String name = queryParameters.getSingleParameter(PARAM_NAME).orElse("");
        Set<CustomerStatus> statuses = queryParameters.getSingleParameter(PARAM_STATUS)
                .map(FilterUrlCodec::parseStatuses)
                .orElse(Set.of());
        return new CustomerFilter(name, statuses);
    }

    /**
     * Builds the query string for the given filter, without a leading {@code ?}.
     * Empty for a filter that matches everything.
     */
    static String toQueryString(CustomerFilter filter) {
        List<String> params = new ArrayList<>();
        if (!filter.name().isBlank()) {
            params.add(PARAM_NAME + "=" + encode(filter.name()));
        }
        if (!filter.statuses().isEmpty()) {
            params.add(PARAM_STATUS + "=" + orderedStatusNames(filter.statuses()));
        }
        return String.join("&", params);
    }

    private static Set<CustomerStatus> parseStatuses(String raw) {
        Set<CustomerStatus> result = new LinkedHashSet<>();
        for (String part : raw.split(",")) {
            if (!part.isBlank()) {
                result.add(CustomerStatus.valueOf(part.trim()));
            }
        }
        return result;
    }

    private static String orderedStatusNames(Set<CustomerStatus> statuses) {
        return Arrays.stream(CustomerStatus.values())
                .filter(statuses::contains)
                .map(Enum::name)
                .collect(Collectors.joining(","));
    }

    private static String encode(String value) {
        return URLEncoder.encode(value, StandardCharsets.UTF_8).replace("+", "%20");
    }
}
