import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

class FilterUrlCodecTest {

    @Test
    void emptyFilterProducesNoQueryString() {
        assertEquals("", FilterUrlCodec.toQueryString(CustomerFilter.EMPTY));
    }

    @Test
    void emptyQueryParametersProduceEmptyFilter() {
        CustomerFilter filter = FilterUrlCodec.parse(QueryParameters.empty());
        assertEquals("", filter.name());
        assertTrue(filter.statuses().isEmpty());
    }

    @Test
    void statusesAreJoinedInDeclarationOrderRegardlessOfSelectionOrder() {
        CustomerFilter filter = new CustomerFilter("", Set.of(CustomerStatus.CLOSED, CustomerStatus.ACTIVE));
        assertEquals("status=ACTIVE,CLOSED", FilterUrlCodec.toQueryString(filter));
    }

    @Test
    void nameAndStatusRoundTripThroughTheQueryString() {
        CustomerFilter original = new CustomerFilter("vir", Set.of(CustomerStatus.ACTIVE, CustomerStatus.CLOSED));
        String queryString = FilterUrlCodec.toQueryString(original);

        CustomerFilter parsed = FilterUrlCodec.parse(QueryParameters.fromString(queryString));

        assertEquals(original.name(), parsed.name());
        assertEquals(original.statuses(), parsed.statuses());
    }

    @Test
    void nameWithSpacesAndAccentsRoundTrips() {
        CustomerFilter original = new CustomerFilter("ada mäkinen", Set.of());
        String queryString = FilterUrlCodec.toQueryString(original);

        CustomerFilter parsed = FilterUrlCodec.parse(QueryParameters.fromString(queryString));

        assertEquals("ada mäkinen", parsed.name());
    }

    @Test
    void blankNameIsOmittedFromTheQueryString() {
        CustomerFilter filter = new CustomerFilter("   ", Set.of(CustomerStatus.PENDING));
        assertEquals("status=PENDING", FilterUrlCodec.toQueryString(filter));
    }

    @Test
    void statusParameterParsesCommaSeparatedNames() {
        QueryParameters params = QueryParameters.fromString("status=ACTIVE,CLOSED");
        CustomerFilter filter = FilterUrlCodec.parse(params);
        assertEquals(Set.of(CustomerStatus.ACTIVE, CustomerStatus.CLOSED), filter.statuses());
    }
}
