        page.waitForTimeout(600);

        assertTrue(page.url().endsWith("/?name=m%C3%A4kinen"),
                "Unexpected URL after typing a name filter: " + page.url());

        MultiSelectComboBoxElement statusFilter = new MultiSelectComboBoxElement(
                page.locator("vaadin-multi-select-combo-box"));
        statusFilter.selectItem("ACTIVE");
        statusFilter.selectItem("CLOSED");
        page.waitForTimeout(300);

        assertTrue(page.url().contains("status=ACTIVE,CLOSED"),
                "Expected a literal comma-separated status list in the URL: " + page.url());

        page.reload();
        page.waitForSelector("vaadin-grid");
        assertEquals("mäkinen", TextFieldElement.byPlaceholder(page, "Filter by name").getValue());

        GridElement grid = new GridElement(page.locator("vaadin-grid"));
        assertEquals(10, grid.getRowCount());
    }
}
