@@ -0,0 +1,61 @@
+package com.example.customers.domain;
+
+import java.util.Set;
+
+import org.junit.jupiter.api.Test;
+
+import static org.junit.jupiter.api.Assertions.assertFalse;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+class CustomerFilterTest {
+
+    private static final Customer AALTONEN =
+            new Customer(1, "Ada", "Aaltonen", "ada@example.com", "Finland", CustomerStatus.ACTIVE);
+    private static final Customer MAKINEN =
+            new Customer(2, "Joséphine", "Mäkinen", "jo@example.com", "Finland", CustomerStatus.CLOSED);
+
+    @Test
+    void emptyFilterMatchesEveryCustomer() {
+        assertTrue(CustomerFilter.EMPTY.matches(AALTONEN));
+        assertTrue(CustomerFilter.EMPTY.matches(MAKINEN));
+    }
+
+    @Test
+    void everyTermMustMatchFirstOrLastNameRegardlessOfOrder() {
+        assertTrue(new CustomerFilter("ada aal", Set.of()).matches(AALTONEN));
+        assertTrue(new CustomerFilter("aal ada", Set.of()).matches(AALTONEN));
+        assertFalse(new CustomerFilter("ada virtanen", Set.of()).matches(AALTONEN));
+    }
+
+    @Test
+    void whitespaceAroundAndBetweenTermsIsNotSignificant() {
+        assertTrue(new CustomerFilter("  ada   aal  ", Set.of()).matches(AALTONEN));
+    }
+
+    @Test
+    void matchingIgnoresCaseAndAccentsInBothDirections() {
+        assertTrue(new CustomerFilter("makinen", Set.of()).matches(MAKINEN));
+        assertTrue(new CustomerFilter("MAKINEN", Set.of()).matches(MAKINEN));
+        assertTrue(new CustomerFilter("mäkinen", Set.of()).matches(MAKINEN));
+        assertTrue(new CustomerFilter("josephine", Set.of()).matches(MAKINEN));
+    }
+
+    @Test
+    void emptyStatusSetMatchesEveryStatus() {
+        assertTrue(new CustomerFilter("", Set.of()).matches(AALTONEN));
+        assertTrue(new CustomerFilter("", Set.of()).matches(MAKINEN));
+    }
+
+    @Test
+    void nonEmptyStatusSetRestrictsToThoseStatuses() {
+        CustomerFilter activeOnly = new CustomerFilter("", Set.of(CustomerStatus.ACTIVE));
+        assertTrue(activeOnly.matches(AALTONEN));
+        assertFalse(activeOnly.matches(MAKINEN));
+    }
+
+    @Test
+    void bothFiltersMustMatch() {
+        CustomerFilter filter = new CustomerFilter("ada", Set.of(CustomerStatus.CLOSED));
+        assertFalse(filter.matches(AALTONEN));
+    }
+}
